class Solution {
public:
    double probabilityOfHeads(std::vector<double>& prob, int target) {
        std::vector<double> dp(target + 1, 0.0);
        dp[0] = 1.0;
        for (double p : prob) {
            for (int k = target; k >= 0; --k) {
                dp[k] = dp[k] * (1.0 - p) + (k > 0 ? dp[k - 1] * p : 0.0);
            }
        }
        return dp[target];
    }
};

class Solution {
    public double probabilityOfHeads(double[] prob, int target) {
        double[] dp = new double[target + 1];
        dp[0] = 1.0;
        for (double p : prob) {
            for (int k = target; k >= 0; k--) {
                dp[k] = dp[k] * (1.0 - p) + (k > 0 ? dp[k - 1] * p : 0.0);
            }
        }
        return dp[target];
    }
}

var probabilityOfHeads = function(prob, target) {
    const dp = new Array(target + 1).fill(0.0);
    dp[0] = 1.0;
    for (const p of prob) {
        for (let k = target; k >= 0; k--) {
            dp[k] = dp[k] * (1.0 - p) + (k > 0 ? dp[k - 1] * p : 0.0);
        }
    }
    return dp[target];
